import * as vscode from 'vscode';
import * as proc from 'child_process';
import * as net from 'net';
import * as stream from 'stream';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

// Declarations from the Debug Adapter Protocol implementation
import { DebugProtocol } from '@vscode/debugprotocol';
import { OutputEvent, TerminatedEvent } from '@vscode/debugadapter';

export function activate(context: vscode.ExtensionContext) {
	const logger = vscode.window.createOutputChannel('DOSBox', { log: true });
	context.subscriptions.push(logger);

	const provider = new DosDebugConfigProvider();
	context.subscriptions.push(vscode.debug.registerDebugConfigurationProvider('dosbox', provider));
	const factory = new DosDebugDescriptorFactory(logger);
	context.subscriptions.push(vscode.debug.registerDebugAdapterDescriptorFactory('dosbox', factory));
}

class DosDebugConfigProvider implements vscode.DebugConfigurationProvider {

	resolveDebugConfiguration(_folder: vscode.WorkspaceFolder | undefined, configuration: vscode.DebugConfiguration, _token?: vscode.CancellationToken): vscode.ProviderResult<vscode.DebugConfiguration> {
		// Assume dynamic debug configuration if type and request are not given
		if (!configuration.type && !configuration.request && !configuration.name) {
			configuration.name = 'Launch DOS Executable';
			configuration.type = 'dosbox';
			configuration.request = 'launch';
		}
		configuration.mount = configuration.mount || '${fileWorkspaceFolder}';
		configuration.cd = configuration.cd || '${relativeFileDirname}';
		configuration.program = configuration.program || '${fileBasename}';

		// Get configuration from settings if not specified in the debug config
		const settingsConfig = vscode.workspace.getConfiguration('dosbox');

		configuration.port = configuration.port || settingsConfig.get<number>('debug.port', 2444);
		configuration.host = configuration.host || settingsConfig.get<string>('debug.host', 'localhost');

		// We can assume that DOSBox Staging is already running if we're
		// attaching instead of launching and so don't need to validate the
		// executable
		if (configuration.request === 'launch') {
			configuration.dosboxExe = configuration.dosboxExe || settingsConfig.get<string>('executablePath', '');

			// Validate configured DOSBox Staging executable path, or try to
			// detect it if not specified
			if (configuration.dosboxExe) {
				if (!path.isAbsolute(configuration.dosboxExe) || !fs.existsSync(configuration.dosboxExe)) {
					vscode.commands.executeCommand('workbench.action.openSettings', 'dosbox.executablePath');
					throw new Error('The path to the DOSBox Staging executable is not absolute or does not exist. Configure it in settings.');
				}
			} else {
				const pathEnv = process.env.PATH || "";
				const paths = pathEnv.replace(/["]+/g, "").split(path.delimiter).filter((p) => !!p);
				const candidates = paths.map((p) => path.join(p, 'dosbox')).filter((p) => fs.existsSync(p));
				if (!candidates.length) {
					vscode.commands.executeCommand('workbench.action.openSettings', 'dosbox.executablePath');
					throw new Error('No DOSBox Staging executable was found in the PATH. Configure it in settings.');
				}
				configuration.dosboxExe = candidates[0];
			}
		}
		return configuration;
	}
}

class DosDebugDescriptorFactory implements vscode.DebugAdapterDescriptorFactory {

	constructor(private readonly logger: vscode.LogOutputChannel) { }

	async createDebugAdapterDescriptor(session: vscode.DebugSession, _executable: vscode.DebugAdapterExecutable | undefined): Promise<vscode.ProviderResult<vscode.DebugAdapterDescriptor>> {
		const da = new ProxyingDosDebugAdapter(session.configuration, this.logger);
		return new vscode.DebugAdapterInlineImplementation(da);
	}
}

/**
 * Manages the connection to a DOSBox Staging debug server, either by attaching
 * directly to an existent DOSBos Staging process, or by launching our own
 * DOSBox Staging process and attaching to that.
 */
abstract class DosDebugProcessConnection {
	private debugServerProcess?: proc.ChildProcess;
	private debugServerSocket?: net.Socket;

	constructor(private configuration: vscode.DebugConfiguration, protected logger: vscode.LogOutputChannel) { }

	protected async launchOrAttach(): Promise<{ connected: boolean, reason?: string }> {
		const attachOnly = this.configuration.request === 'attach';
		try {
			this.debugServerProcess = !attachOnly ? await this.spawnDosboxProcess() : undefined;
			this.debugServerSocket = await this.connectDosboxSocket();

			this.onStart(this.debugServerSocket, this.debugServerSocket);
		} catch (error) {
			const e = error as Error;
			return { connected: false, reason: e.message };
		}
		return { connected: true };
	}

	/**
	 * Will be called once a connection is established to the debug server
	 * running inside the DOSBox Staging process.
	 * 
	 * @param readable Input stream from the debug server.
	 * @param writable Output stream to the debug server.
	 */
	protected abstract onStart(readable: stream.Readable, writable: stream.Writable): void;

	/**
	 * When launching (not attaching) this will be called whenever the DOSBox
	 * Staging process writes to stdout.
	 * 
	 * @param message Some text.
	 */
	protected abstract onStdout(message: string): void;

	/**
	 * When launching (not attaching) this will be called whenever the DOSBox
	 * Staging process writes to stderr.
	 * 
	 * @param message Some text.
	 */
	protected abstract onStderr(message: string): void;

	private spawnDosboxProcess(): Promise<proc.ChildProcess> {
		// Generate temporary DOSBox config file
		const conf = `[debugger]\nport = ${this.configuration.port}\n` +
			`[autoexec]\nMOUNT N ${this.configuration.mount}\nN:\nCD ${this.configuration.cd}\nDEBUG.COM ${this.configuration.program}\n`;
		const tmpDir = fs.mkdtempSync(os.tmpdir() + path.sep + 'dosbox-debug-');
		const confFile = tmpDir + path.sep + 'conf';
		fs.writeFileSync(confFile, conf);

		const exe = this.configuration.dosboxExe;
		const args = ['--conf', confFile];
		this.logger.info(`Starting DOSBox Staging with command: ${exe} ${args.join(' ')}`);

		// Spawn an instance of DOSBox
		return new Promise<proc.ChildProcess>((resolve, reject) => {
			let started = false;
			const p = proc.spawn(exe, args, {
				stdio: ['pipe', 'pipe', 'pipe']
			});

			const timeout: NodeJS.Timeout = setTimeout(() => {
				p.kill();
				reject(new Error('Timed out waiting for the debug server to start, was DOSBox Staging compiled with "-Denable_debugger=dap"?'));
			}, 10_000);

			const spawnError = (error: Error) => {
				clearTimeout(timeout);
				reject(new Error(`OS failure to spawn process due to: ${error.message}`));
			};

			const spawnSuccess = () => {
				clearTimeout(timeout);
				p.removeListener('error', spawnError);
				started = true;
				this.logger.info('Detected debug server is available');
				resolve(p);
			};

			p.stdout.on('data', (chunk) => {
				const msg = chunk.toString();
				this.onStdout(msg);
			});
			p.stderr.on('data', (chunk) => {
				// Wait for a message we can expect DOSBox to emit once the debug
				// server is ready to accept connections
				const msg = chunk.toString();
				if (!started && msg.includes('DEBUGGER: Debug server listening on port')) {
					spawnSuccess();
				}
				this.onStderr(msg);
			});
			p.on('close', (code, signal) => {
				if (code) {
					this.logger.info(`Process with PID ${p.pid} exited with code: ${code}`);
				} else if (signal) {
					this.logger.info(`Process with PID ${p.pid} exited due to signal: ${signal}`);
				}
				fs.rmSync(tmpDir, {
					force: true,
					recursive: true
				});
			});
			p.on('spawn', () => this.logger.info(`Started process with PID ${p.pid}`));
			p.on('error', spawnError);
		});
	}

	private connectDosboxSocket(): Promise<net.Socket> {
		const port = this.configuration.port;
		this.logger.info(`Connecting to DOSBox Staging debug server running on port: ${port}`);

		// Attempt socket connection
		return new Promise<net.Socket>((resolve, reject) => {
			const socket = net.createConnection(port, this.configuration.host, () => {
				clearTimeout(timeout);
				this.logger.info('Successfully connected to the debug server');
				resolve(socket);
			});
			const timeout: NodeJS.Timeout = setTimeout(() => {
				reject(new Error(`Timed out connecting to the debug server, is a firewall blocking port ${port}?`));
				socket?.destroy();
			}, 1_000);
			socket.on('close', () => this.logger.info('Disconnected from debug server'));
		});
	}

	async dispose(): Promise<void> {
		this.debugServerSocket?.end();
		if (!this.debugServerProcess) {
			// Had never started
			return;
		}
		const process = this.debugServerProcess;
		this.debugServerProcess = undefined;
		if (process.exitCode !== null) {
			// Already exited
			return;
		}
		await new Promise<void>((resolve) => {
			const timeout: NodeJS.Timeout = setTimeout(() => {
				// Process *should* exit gracefully on receipt of termination signal
				process.kill();
			}, 1_000);
			process.on('exit', (_code, _signal) => {
				clearTimeout(timeout);
				resolve();
			});
		});
	}
}

/**
 * A debug adapter implementation that proxies comms between the VSCode debug
 * client and the DOSBox Staging debug server. In the case we want to launch
 * our own DOSBox Staging instead of attaching to an existent process, this
 * allows us to capture any stdout/stderr output and convert them into useful
 * debug adapter protocol output events.
 */
class ProxyingDosDebugAdapter extends DosDebugProcessConnection implements vscode.DebugAdapter {
	private fettler: ProtocolFettler = new ProtocolFettler((message) => this.sendMessageToClient(message));

	private readable?: stream.Readable;
	private writable?: stream.Writable;
	private terminated = false;
	private connected?: Promise<{ connected: boolean; reason?: string }>;

	// Event emitter that fires when DAP messages are received
	private readonly messageEmitter = new vscode.EventEmitter<vscode.DebugProtocolMessage>();
	readonly onDidSendMessage = this.messageEmitter.event;

	constructor(configuration: vscode.DebugConfiguration, logger: vscode.LogOutputChannel) {
		super(configuration, logger);
	}

	/**
	 * Called by the VSCode debug client to send messages to the debug server.
	 * 
	 * @param message A debug protocol message.
	 */
	public async handleMessage(message: vscode.DebugProtocolMessage): Promise<void> {
		await this.sendMessageToServer(message);
	}

	// Proxy messages from the debug server to the VSCode client
	private sendMessageToClient(message: vscode.DebugProtocolMessage): void {
		this.messageEmitter.fire(message);
	}

	// Proxy messages from the VSCode client to the debug server
	private async sendMessageToServer(message: vscode.DebugProtocolMessage): Promise<void> {
		const m = message as any;

		// Attempt to launch/attach to DOSBox Staging if we're not connected
		if (!this.connected) {
			// The debug server expects our first message upon connection to be
			// an initialise request, so fail if that's not the case
			if (m.type === 'request' && m.command === 'initialize') {
				this.connected = this.launchOrAttach();
			} else {
				this.connected = Promise.resolve({
					connected: false,
					reason: `the first message must be an initialize request`
				});
			}
		}
		const { connected, reason } = await this.connected;

		// Perform the actual sending of the message
		if (connected) {
			const json = JSON.stringify(message) ?? '';
			if (this.writable) {
				this.writable.write(`Content-Length: ${Buffer.byteLength(json, 'utf8')}\r\n\r\n${json}`, 'utf8',
					(error) => this.terminate(error)
				);
			}
			return;
		}

		// A connection couldn't be established, or DOSBos Staging couldn't
		// be started, so manually send a response back to the VSCode debug
		// client containing the error message
		if (m.type === 'request') {
			const req = message as DebugProtocol.Request;
			this.sendMessageToClient({
				seq: 0,
				type: 'response',
				request_seq: req.seq,
				success: false,
				command: req.command,
				message: reason
			});
		}
	}

	// Send a terminate event to the VSCode debug client if we haven't already
	private terminate(error: Error | null | undefined) {
		if (error) {
			if (this.terminated) {
				return;
			}
			this.terminated = true;
			this.sendMessageToClient(new TerminatedEvent());
			// TODO report/log the error?
		}
	}

	// Setup streams
	protected async onStart(readable: stream.Readable, writable: stream.Writable): Promise<void> {
		this.readable = readable;
		this.writable = writable;
		this.readable.on('data', (data: Buffer) => this.fettler.parse(data));
		this.readable.on('error', (error) => this.terminate(error));
		this.readable.once('close', () => this.readable = undefined);
	}

	protected onStdout(message: string): void {
		this.sendMessageToClient(new OutputEvent(message, 'stdout'));
	}

	protected onStderr(message: string): void {
		this.sendMessageToClient(new OutputEvent(message, 'stderr'));
	}

	async dispose(): Promise<void> {
		if (this.connected === undefined) {
			return;
		}
		this.connected = undefined;
		await super.dispose();
	}
}

/**
 * Utility class to parse out whole protocol messages from the raw bytes
 * received over, e.g. a socket.
 */
class ProtocolFettler {
	private buffer = Buffer.alloc(0);
	private contentLength = -1;

	/**
	 * Creates a protocol fettler. The specified function `callback` will be
	 * called for every fully formed protocol message that is parsed out of
	 * the bytes received by the {@link parse} function.
	 * 
	 * @param callback The callback function.
	 */
	constructor(private readonly callback: (message: vscode.DebugProtocolMessage) => void) { }

	/**
	 * Add more data to be parsed into debug protocol messages.
	 * 
	 * @param data Raw byte buffer.
	 */
	public parse(data: Buffer): void {
		this.buffer = Buffer.concat([this.buffer, data]);
		while (true) {
			if (this.contentLength >= 0) {
				if (this.buffer.length >= this.contentLength) {
					const message = this.buffer.toString('utf8', 0, this.contentLength);
					this.buffer = this.buffer.subarray(this.contentLength);
					this.contentLength = -1;
					if (message.length > 0) {
						const msg = JSON.parse(message) as vscode.DebugProtocolMessage;
						this.callback(msg);
					}
					continue;
				}
			} else {
				const idx = this.buffer.indexOf('\r\n\r\n');
				if (idx !== -1) {
					const header = this.buffer.toString('utf8', 0, idx);
					const lines = header.split('\r\n');
					for (const line of lines) {
						const pair = line.split(/: +/);
						if (pair[0] === 'Content-Length') {
							this.contentLength = +pair[1];
						}
					}
					this.buffer = this.buffer.subarray(idx + 4);
					continue;
				}
			}
			break;
		}
	}
}

