{
  "name": "dosbox-debug",
  "displayName": "DOSBox Staging Debugging Tools",
  "version": "0.0.1",
  "description": "Debug, disassembly, and decompilation tools for the DOSBox Staging integrated debugger.",
  "publisher": "sillybudgie",
  "license": "MIT",
  "author": {
    "name": "Mat Booth",
    "email": "dosbox@matbooth.co.uk"
  },
  "contributors": [],
  "engines": {
    "vscode": "^1.100.0"
  },
  "categories": [
    "Debuggers",
    "Other"
  ],
  "keywords": [
    "debug",
    "debugging",
    "disassembly",
    "decompilation",
    "dosbox",
    "dos",
    "msdos"
  ],
  "icon": "media/dos-icon-square.png",
  "homepage": "https://github.com/SillyBudgieIndustries/vscode-dosbox-debug",
  "repository": {
    "type": "git",
    "url": "https://github.com/SillyBudgieIndustries/vscode-dosbox-debug.git"
  },
  "bugs": {
    "url": "https://github.com/SillyBudgieIndustries/vscode-dosbox-debug/issues"
  },
  "main": "./dist/extension.js",
  "activationEvents": [],
  "contributes": {
    "languages": [
      {
        "id": "dosmz",
        "extensions": [
          ".EXE",
          ".COM"
        ],
        "aliases": [
          "DOS Executable",
          "dos"
        ],
        "icon": {
          "light": "./media/dos-icon-cropped.png",
          "dark": "./media/dos-icon-cropped.png"
        }
      }
    ],
    "menus": {},
    "commands": [],
    "customEditors": [
      {
        "viewType": "dosbox.executableEditor",
        "displayName": "DOS Executable",
        "selector": [
          {
            "filenamePattern": "*.EXE"
          },
          {
            "filenamePattern": "*.COM"
          }
        ],
        "priority": "default"
      }
    ],
    "configuration": {
      "title": "DOSBox",
      "type": "object",
      "properties": {
        "dosbox.executablePath": {
          "type": [
            "string"
          ],
          "description": "Absolute path to the DOSBox Staging executable."
        },
        "dosbox.debug.port": {
          "type": "number",
          "minimum": 1024,
          "maximum": 65535,
          "default": 2444,
          "description": "Non-privileged port (1024-65535) on which the DOSBox Staging debug server is listening."
        },
        "dosbox.debug.host": {
          "type": "string",
          "default": "localhost",
          "description": "Host or IP on which the DOSBox Staging debug server is listening."
        }
      }
    },
    "breakpoints": [
      {
        "language": "dosmz"
      }
    ],
    "debuggers": [
      {
        "type": "dosbox",
        "label": "DOSBox",
        "languages": [
          "dosmz"
        ],
        "configurationAttributes": {
          "launch": {
            "required": [
              "mount",
              "cd",
              "program"
            ],
            "properties": {
              "mount": {
                "type": "string",
                "description": "Directory to mount as a DOS drive using the MOUNT command."
              },
              "cd": {
                "type": "string",
                "description": "Change to this directory on the mounted drive before debugging."
              },
              "program": {
                "type": "string",
                "description": "Name of the DOS executable to debug, e.g. GAME.EXE"
              }
            }
          },
          "attach": {
            "required": [
              "mount",
              "cd",
              "program"
            ],
            "properties": {
              "mount": {
                "type": "string",
                "description": "Directory to mount as a DOS drive using the MOUNT command."
              },
              "cd": {
                "type": "string",
                "description": "Change to this directory on the mounted drive before debugging."
              },
              "program": {
                "type": "string",
                "description": "Name of the DOS executable to debug, e.g. GAME.EXE"
              }
            }
          }
        },
        "configurationSnippets": [
          {
            "label": "DOSBox: Launch",
            "description": "Launch and debug the program in DOSBox Staging",
            "body": {
              "name": "Launch DOS Executable",
              "type": "dosbox",
              "request": "launch",
              "mount": "^\"\\${fileWorkspaceFolder}\"",
              "cd": "^\"\\${relativeFileDirname}\"",
              "program": "^\"\\${fileBasename}\""
            }
          },
          {
            "label": "DOSBox: Attach",
            "description": "Attach to and debug a program already running in DOSBox Staging",
            "body": {
              "name": "Attach to DOS Executable",
              "type": "dosbox",
              "request": "attach",
              "mount": "^\"\\${fileWorkspaceFolder}\"",
              "cd": "^\"\\${relativeFileDirname}\"",
              "program": "^\"\\${fileBasename}\""
            }
          }
        ],
        "initialConfigurations": [
          {
            "name": "Launch DOS Executable",
            "type": "dosbox",
            "request": "launch",
            "mount": "${fileWorkspaceFolder}",
            "cd": "${relativeFileDirname}",
            "program": "${fileBasename}"
          }
        ]
      }
    ]
  },
  "scripts": {
    "vscode:prepublish": "npm run check-types && node esbuild.config.mjs --production",
    "lint": "eslint src",
    "check-types": "tsc --noEmit -p ./",
    "compile": "npm run check-types && node esbuild.config.mjs",
    "watch": "npm-run-all -p watch:*",
    "watch:esbuild": "node esbuild.config.mjs --watch",
    "watch:tsc": "tsc --noEmit --watch -p ./",
    "pretest": "npm run compile && npm run lint",
    "test": "vscode-test"
  },
  "devDependencies": {
    "@types/mocha": "^10.0.10",
    "@types/node": "20.x",
    "@types/react": "^18.3.1",
    "@types/react-dom": "^18.3.1",
    "@types/vscode": "^1.100.0",
    "@typescript-eslint/eslint-plugin": "^8.34.0",
    "@typescript-eslint/parser": "^8.34.0",
    "@vscode/test-cli": "^0.0.11",
    "@vscode/test-electron": "^2.5.2",
    "esbuild": "^0.25.5",
    "eslint": "^9.29.0",
    "npm-run-all": "^4.1.5",
    "typescript": "^5.8.3"
  },
  "dependencies": {
    "@vscode/debugadapter": "^1.68.0",
    "@vscode/debugprotocol": "^1.68.0",
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  }
}
